    $compressedBytes = [Convert]::FromBase64String(($embeddedCore -replace '\s',''))
    $inputStream = New-Object System.IO.MemoryStream(,$compressedBytes)
    $gzipStream = New-Object System.IO.Compression.GzipStream(
        $inputStream,
        [System.IO.Compression.CompressionMode]::Decompress
    )
    $reader = New-Object System.IO.StreamReader(
        $gzipStream,
        [System.Text.Encoding]::UTF8
    )
    $code = $reader.ReadToEnd()
    $reader.Dispose()
    $gzipStream.Dispose()
    $inputStream.Dispose()

    if ([string]::IsNullOrWhiteSpace($code)) {
        throw "V15 固定核心解壓縮失敗。"
    }


    # ============================================================
    # V14.2：官方 WinUtil 版本號檢查
    #
    # 只比較版本號，不比較整份腳本雜湊：
    # - 避免官方只改註解/空白/非版本內容時誤報更新
    # - 不覆蓋固定核心
    # - 不執行官方最新版
    # - 不修改 Tweaks / Config / AppX
    # - 網路失敗時略過，不影響固定核心啟動
    # ============================================================
    try {
        Write-Host "正在檢查官方 WinUtil 版本..." -ForegroundColor DarkCyan

        $fixedVersion = "26.08.19"
        $latestCode = Invoke-RestMethod "https://christitus.com/win" -TimeoutSec 8

        if (-not [string]::IsNullOrWhiteSpace($latestCode)) {

            # 優先抓取常見版本寫法：
            # $sync.version = "26.08.04"
            # Version : 26.08.04
            # Version: 26.08.04
            $latestVersion = $null

            $m = [regex]::Match(
                [string]$latestCode,
                '(?im)^\s*\$sync\.version\s*=\s*["''](?<ver>\d{2}\.\d{2}\.\d{2})["'']'
            )
            if ($m.Success) {
                $latestVersion = $m.Groups['ver'].Value
            }

            if (-not $latestVersion) {
                $m = [regex]::Match(
                    [string]$latestCode,
                    '(?im)^\s*Version\s*:\s*(?<ver>\d{2}\.\d{2}\.\d{2})\s*$'
                )
                if ($m.Success) {
                    $latestVersion = $m.Groups['ver'].Value
                }
            }

            if ($latestVersion) {

                if ($latestVersion -ne $fixedVersion) {
                    Write-Host ""
                    Write-Host "==============================================" -ForegroundColor Yellow
                    Write-Host " 發現新的官方 WinUtil 版本" -ForegroundColor Yellow
                    Write-Host " 固定核心版本：$fixedVersion" -ForegroundColor Yellow
                    Write-Host " 官方版本：    $latestVersion" -ForegroundColor Yellow
                    Write-Host " 目前仍會繼續使用已驗證的固定核心。" -ForegroundColor Yellow
                    Write-Host " 不會自動更新或覆蓋任何檔案。" -ForegroundColor Yellow
                    Write-Host "==============================================" -ForegroundColor Yellow
                    Write-Host ""

                    try {
                        Add-Type -AssemblyName PresentationFramework -ErrorAction Stop
                        [System.Windows.MessageBox]::Show(
                            "偵測到新的官方 WinUtil 版本。`n`n目前繁中固定核心：$fixedVersion`n官方版本：$latestVersion`n`n目前仍會使用已驗證的固定核心，不會自動更新。`n若要升級繁中版，請先比對新版後再製作下一版。",
                            "WinUtil 繁中版－發現官方更新",
                            [System.Windows.MessageBoxButton]::OK,
                            [System.Windows.MessageBoxImage]::Information
                        ) | Out-Null
                    }
                    catch {
                        # 圖形提示失敗時保留 Console 提示即可
                    }
                }
                else {
                    Write-Host "官方版本與目前固定核心相同：$fixedVersion" -ForegroundColor Green
                }
            }
            else {
                Write-Host "無法解析官方版本號，略過版本提示並繼續啟動。" -ForegroundColor DarkYellow
            }
        }
    }
    catch {
        Write-Host "官方版本檢查失敗，略過檢查並繼續啟動固定核心。" -ForegroundColor DarkYellow
    }


