        'ISO verified OK.  Editions found: $($imageInfo.Count)' = 'ISO 驗證成功。找到版本數：$($imageInfo.Count)'
        'ERROR during mount/verify: $errorMessage' = '掛載／驗證時發生錯誤：$errorMessage'
        'An error occurred while mounting or verifying the ISO:`n`n$errorMessage' =
            '掛載或驗證 ISO 時發生錯誤：`n`n$errorMessage'
        'No verified ISO found. Please complete Steps 1 and 2 first.' =
            '尚未找到已驗證的 ISO。請先完成步驟 1 與步驟 2。'
        'Not Ready' = '尚未就緒'
        'Selected edition: $selectedEditionName (Index $selectedWimIndex)' =
            '已選擇版本：$selectedEditionName（索引 $selectedWimIndex）'

        # Modification status
        'Creating working directory: $workDir' = '正在建立工作目錄：$workDir'
        'Copying ISO contents...' = '正在複製 ISO 內容...'
        'Copying ISO contents from $driveLetter to $isoContents...' =
            '正在從 $driveLetter 複製 ISO 內容至 $isoContents...'
        'ISO contents copied.' = 'ISO 內容複製完成。'
        'Preparing setup media...' = '正在準備安裝媒體...'
        'Writing autounattend.xml and edition selection...' = '正在寫入 autounattend.xml 與版本選擇設定...'
        'Preserving install image...' = '正在保留安裝映像...'
        'Dismounting source ISO...' = '正在卸載來源 ISO...'
        'Dismounting original ISO...' = '正在卸載原始 ISO...'
        'Modification complete' = '修改完成'
        'install.wim modification complete. Choose an output option in Step 4.' =
            'install.wim 修改完成。請在步驟 4 選擇輸出方式。'
        'Modification Error' = '修改錯誤'

        # Resume / clean reset
        'Existing Work Found' = '找到既有工作資料'
        'Clean & Reset' = '清理並重設'
        'Resetting UI...' = '正在重設介面...'
        'Resetting interface...' = '正在重設介面...'
        'Temp directory deleted successfully.' = '暫存目錄已成功刪除。'
        'No temp directory found - resetting UI.' = '找不到暫存目錄，正在重設介面。'
        'ERROR during Clean & Reset: $_' = '清理並重設時發生錯誤：$_'
    }

    foreach ($p in $win11CreatorZhTW.GetEnumerator()) {
        $code = $code.Replace($p.Key, $p.Value)
    }




    # ============================================================
    # 1-A. V6/V7：補上 WinUtil 特殊 XAML 的上方導覽文字
    # 官方不是 Content="Install"，而是 <Underline>I</Underline>nstall。
    # 只改 TextBlock 的顯示內容，不改 WPFTab* 名稱或事件。
    # ============================================================
    $topNav = [ordered]@{
        '<Underline>I</Underline>nstall'='安裝軟體'
        '<Underline>T</Underline>weaks'='系統優化'
        '<Underline>C</Underline>onfig'='系統設定'
        '<Underline>U</Underline>pdates'='Windows 更新'
        '<Underline>W</Underline>in11 Creator'='Win11 工具箱'
    }

    foreach ($p in $topNav.GetEnumerator()) {
        $code = $code.Replace($p.Key, $p.Value)
    }

    # ============================================================
    # 1-B. V6/V7：左側動態分類標題只翻「顯示結果」
    # $category 原始值仍保持 ____Actions / __Package Manager / __Selection。
    # 這避免破壞 WinUtil 的內部分類、事件與搜尋邏輯。
    # ============================================================
    $oldCategoryRenderer = '$label.Content = $category -replace ".*__", ""'
    $newCategoryRenderer = @'
$displayCategory = $category -replace ".*__", ""
            $label.Content = switch ($displayCategory) {
                "Actions"         { "動作" }
                "Package Manager" { "套件管理" }
                "Selection"       { "選擇管理" }
                "Essential Tweaks" { "基本優化" }
                "Customize Preferences" { "個人化設定" }
                "Features" { "Windows 功能" }
                "Fixes" { "修復工具" }
                "Legacy Windows Panels" { "傳統 Windows 控制台" }
                "z__Advanced Tweaks - CAUTION" { "進階優化－注意" }
                "Performance Plans - NOT FOR LAPTOPS" { "效能電源方案－不建議筆電" }
                default { $displayCategory }
            }
'@
    $code = $code.Replace($oldCategoryRenderer, $newCategoryRenderer.TrimEnd())

    # ============================================================
    # 2. 動態 Content 顯示名稱
    # 關鍵：只改 "Content": "xxx"
    # 絕對不改 "category": "xxx"
    # ============================================================
    $contentMap = [ordered]@{
        # 左側動態操作區
        'Install/Upgrade Applications'='安裝／升級應用程式'
        'Uninstall Applications'='解除安裝應用程式'
        'Upgrade all Applications'='升級所有應用程式'
        'Collapse All Categories'='收合全部分類'
        'Expand All Categories'='展開全部分類'
        'Clear Selection'='清除選取'
        'Show Installed Apps'='顯示已安裝的應用程式'
        'Selected Apps: 0'='已選取 App：0'
        'Free and Open Source Software'='自由與開放原始碼軟體'

        # 安裝頁面 / 常用 App
        'DISMTools'='DISM 工具'
        'PowerToys'='PowerToys（工具集）'
        'Process Explorer'='Process Explorer（程序總管）'
        'Process Monitor'='Process Monitor（程序監視器）'
        'Windows Terminal'='Windows 終端機'
        'Joplin'='Joplin（筆記軟體）'
        'LibreOffice'='LibreOffice（文書套件）'
        'NAPS2 (Scanner)'='NAPS2（掃描工具）'
        'Obsidian'='Obsidian（筆記軟體）'
        'Okular'='Okular（文件檢視器）'
        'ONLYOFFICE Desktop'='ONLYOFFICE 桌面版'
        'PDF24 Creator'='PDF24 Creator（PDF 工具）'
        'PDFgear'='PDFgear（PDF 編輯器）'
        'PDFsam Basic'='PDFsam Basic（PDF 分割合併）'
        'Sumatra PDF'='Sumatra PDF（PDF 檢視器）'
        'Xournal++'='Xournal++（手寫筆記）'
        '7-Zip'='7-Zip（壓縮工具）'

        # Tweaks
        'Activity History - Disable'='活動歷程記錄－關閉'
        'Hibernation - Disable'='休眠－關閉'
        'Widgets - Remove'='小工具－移除'
        'Start Menu Previous Layout - Enable'='開始功能表舊版配置－啟用'
        'Microsoft Store Recommended Search Results - Disable'='Microsoft Store 推薦搜尋結果－關閉'
        'Location Tracking - Disable'='位置追蹤－關閉'
        'Services - Set to Manual'='服務－設為手動'
