        'Settings Home Page'='Windows 設定首頁'
        'Start Menu Bing Search'='開始功能表 Bing 搜尋'
        'Logon Screen Acrylic Blur'='登入畫面壓克力模糊'
        'Lock Screen - Disable'='鎖定畫面－關閉'
        'Start Menu Recommendations'='開始功能表建議內容'
        'Sticky Keys'='相黏鍵'
        'Taskbar Centered Icons'='工作列圖示置中'
        'Taskbar Search Icon'='工作列搜尋'
        'Taskbar Task View Icon'='工作列工作檢視'
        'Game Mode'='遊戲模式'
        'Enable Long Paths'='啟用長路徑支援'
        'O&O ShutUp10++ - Run'='O&O ShutUp10++－執行'
        'DNS - Set to:'='DNS－設定為：'
        'Ultimate Performance Profile - Enable'='終極效能－啟用'
        'Ultimate Performance Profile - Disable'='終極效能－關閉'

        # Windows Features / Config
        '.NET Framework (Versions 2, 3, 4) - Enable'='.NET Framework（2、3、4）－啟用'
        'NTP Server - Enable'='NTP 時間伺服器－啟用'
        'Hyper-V - Enable'='Hyper-V－啟用'
        'Legacy Media Components (WMP, DirectPlay) - Enable'='傳統媒體元件－啟用'
        'Windows Subsystem for Linux (WSL) - Enable'='Windows Linux 子系統（WSL）－啟用'
        'Network File System (NFS) - Enable'='網路檔案系統（NFS）－啟用'
        'Registry Backup (Daily Task 12:30am) - Enable'='登錄檔每日備份－啟用'
        'Legacy F8 Boot Recovery - Enable'='傳統 F8 開機修復－啟用'
        'Legacy F8 Boot Recovery - Disable'='傳統 F8 開機修復－關閉'
        'Windows Sandbox - Enable'='Windows 沙盒－啟用'
        'Install Features'='安裝 Windows 功能'
        'AutoLogon - Run'='自動登入－執行'
        'Windows Update - Reset'='Windows Update－重設'
        'Network - Reset'='網路－重設'
        'System Corruption Scan - Run'='系統損毀掃描－執行'
        'WinGet - Reinstall'='WinGet－重新安裝'

        # 傳統控制台
        'Computer Management'='電腦管理'
        'Control Panel'='控制台'
        'Mouse Properties'='滑鼠內容'
        'Network Connections'='網路連線'
        'Power Panel'='電源選項'
        'Printer Panel'='印表機'
        'Programs and Features'='程式和功能'
        'Region'='地區'
        'Security and Maintenance'='安全性與維護'
        'Sound Settings'='音效設定'
        'System Properties'='系統內容'
        'Time and Date'='日期與時間'
        'Windows Defender Firewall'='Windows Defender 防火牆'
        'Windows Restore'='Windows 系統還原'
        'OpenSSH Server - Enable'='OpenSSH 伺服器－啟用'
    }

    foreach ($p in $contentMap.GetEnumerator()) {
        $old = '"Content": "' + $p.Key + '"'
        $new = '"Content": "' + $p.Value + '"'
        $code = $code.Replace($old, $new)
    }

    # ============================================================
    # 3. 常見 Description 中文化
    # 仍只改顯示說明，不碰功能欄位
    # ============================================================
    $descMap = [ordered]@{
        'Disables Microsoft Telemetry.'='關閉 Microsoft 遙測與診斷資料收集。'
        'Stops Windows from using your bandwidth to upload updates to other PCs on the internet or local network.'='禁止 Windows 使用你的網路頻寬將更新傳送給其他電腦。'
        'Removes the annoying widgets in the bottom left of the Taskbar.'='移除工作列上的 Windows 小工具。'
        'Storage Sense deletes temp files automatically.'='關閉會自動清理暫存檔的儲存空間感知器。'
        'Removes and disables all AI features/packages'='移除並關閉 Windows AI、Copilot 與相關 AI 功能。'
    }

    foreach ($p in $descMap.GetEnumerator()) {
        $old = '"Description": "' + $p.Key + '"'
        $new = '"Description": "' + $p.Value + '"'
        $code = $code.Replace($old, $new)
    }



    Write-Host "V15 固定核心繁體中文化完成，正在啟動 WinUtil..." -ForegroundColor Green

    # 與 irm | iex 類似：在記憶體執行固定核心，不直接執行外部 ps1。
    & ([ScriptBlock]::Create($code))
}
catch {
    Write-Host ""
    Write-Host "WinUtil V15 啟動失敗：" -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    Write-Host ""
    Write-Host "詳細位置：" -ForegroundColor Yellow
    Write-Host $_.ScriptStackTrace -ForegroundColor Yellow
    Write-Host ""
    Read-Host "按 Enter 關閉"
}